\documentclass{article}
\usepackage{pgfplots}
\usepgfplotslibrary{polar}
\pgfplotsset{compat=1.18}

\begin{document}

\begin{figure}[ht]
\centering
\begin{tikzpicture}
\begin{polaraxis}[
    width=8cm,
    height=8cm,
    grid=both,
    major grid style={gray!50},
    minor grid style={gray!20},
    xtick={0,60,...,300},
    xticklabels={数学, 物理, 化学, 生物, 英语, 历史},
    ytick={0,20,40,60,80,100},
    ymin=0,
    ymax=100,
    yticklabels={0,20,40,60,80,100},
    ylabel=分数,
    legend style={at={(0.5,-0.1)}, anchor=north, legend columns=3},
    title=学生成绩雷达图
]

% 学生A的数据
\addplot+[mark=*, line width=1.5pt, fill opacity=0.3, fill=red!30] 
    coordinates {
        (0,85)   % 数学
        (60,78)  % 物理
        (120,92) % 化学
        (180,88) % 生物
        (240,76) % 英语
        (300,81) % 历史
        (360,85) % 闭合图形
    };

% 学生B的数据
\addplot+[mark=square*, line width=1.5pt, fill opacity=0.3, fill=blue!30] 
    coordinates {
        (0,92)   % 数学
        (60,85)  % 物理
        (120,78) % 化学
        (180,82) % 生物
        (240,88) % 英语
        (300,75) % 历史
        (360,92) % 闭合图形
    };

% 学生C的数据
\addplot+[mark=triangle*, line width=1.5pt, fill opacity=0.3, fill=green!30] 
    coordinates {
        (0,78)   % 数学
        (60,90)  % 物理
        (120,85) % 化学
        (180,79) % 生物
        (240,92) % 英语
        (300,88) % 历史
        (360,78) % 闭合图形
    };

\legend{学生A, 学生B, 学生C}

\end{polaraxis}
\end{tikzpicture}
\caption{三位学生在不同科目上的成绩对比雷达图}
\end{figure}

\end{document}
